def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    bg = background(g)
    # find the 8-lines: vertical components touching the top edge
    lines = []
    for c in components(g == 8):
        ys = [p[0] for p in c]; xs = set(p[1] for p in c)
        if min(ys) == 0 and len(xs) == 1:
            lines.append((max(ys), xs.pop()))
    lines.sort(key=lambda t: t[1])
    for ybot, x in lines:
        y = ybot
        while y + 1 < H:
            if g[y + 1, x] == 2:
                # extent of the bar on row y+1
                x0 = x
                while x0 - 1 >= 0 and g[y + 1, x0 - 1] == 2:
                    x0 -= 1
                x1 = x
                while x1 + 1 < W and g[y + 1, x1 + 1] == 2:
                    x1 += 1
                dl = x - (x0 - 1); dr = (x1 + 1) - x
                if dr <= dl and x1 + 1 < W:
                    nx = x1 + 1
                elif x0 - 1 >= 0:
                    nx = x0 - 1
                else:
                    nx = x1 + 1
                step = 1 if nx > x else -1
                for xx in range(x, nx + step, step):
                    if g[y, xx] == bg:
                        g[y, xx] = 8
                x = nx
                if x < 0 or x >= W:
                    break
            else:
                y += 1
                if g[y, x] == bg:
                    g[y, x] = 8
        emit(g.copy(), f"Extended the 8-line from column {x if False else ''}".strip() +
             " down to the bottom, detouring around any 2-bar to its nearer side (ties go right).")
    emit(g.copy(), "All lines extended: final grid.")
    return g
